function allApps(){return [...APPS,...STORE_CATALOG.filter(a=>installedApps().includes(a[0]))]}
function pinned(){try{return JSON.parse(localStorage.getItem('myos-pinned')||'["files","browser","editor","settings"]')}catch{return ['files','browser','editor','settings']}}function shortcuts(){try{return JSON.parse(localStorage.getItem('myos-shortcuts')||'[]')}catch{return []}}function renderApps(){const pins=pinned(),desk=shortcuts();const tile=a=>'<div class="launcher-app-wrap"><button class="app-tile" data-app="'+a[0]+'"><i>'+a[1]+'</i>'+a[2]+'</button><button class="pin-app" data-pin="'+a[0]+'" title="'+(pins.includes(a[0])?'Unpin':'Pin')+'">'+(pins.includes(a[0])?'★':'☆')+'</button><button class="shortcut-app" data-shortcut="'+a[0]+'" title="'+(desk.includes(a[0])?'Remove desktop shortcut':'Add desktop shortcut')+'">'+(desk.includes(a[0])?'×':'↗')+'</button></div>';const apps=allApps();const favorites=apps.filter(a=>pins.includes(a[0]));$('#launcher-apps').innerHTML='<section class="launcher-section"><div class="launcher-label">PINNED APPS</div><div class="app-grid">'+(favorites.map(tile).join('')||'<p class="muted">Pin apps with ☆ to keep them here.</p>')+'</div></section><section class="launcher-section"><div class="launcher-label">ALL APPS</div><div class="app-grid">'+apps.map(tile).join('')+'</div></section>';$('#dock-apps').innerHTML='';const deskEl=$('#desktop-icons'),cellW=88,cellH=100,pad=18,cols=Math.max(1,Math.floor(Math.max(0,deskEl.clientWidth-pad*2)/cellW));const positions=(()=>{try{return JSON.parse(localStorage.getItem('myos-shortcut-positions')||'{}')}catch{return {}}})();const occupied=new Set();deskEl.innerHTML=desk.map(id=>{let a=apps.find(x=>x[0]===id);if(!a)return '';let p=positions[id],col,row;if(p&&Number.isFinite(Number(p.x))&&Number.isFinite(Number(p.y))){col=Math.max(0,Math.min(cols-1,Math.round((Number(p.x)-pad)/cellW)));row=Math.max(0,Math.round((Number(p.y)-pad)/cellH));}else{col=0;row=0;while(occupied.has(col+','+row)){col++;if(col>=cols){col=0;row++}}}while(occupied.has(col+','+row)){col++;if(col>=cols){col=0;row++}}occupied.add(col+','+row);const x=pad+col*cellW,y=pad+row*cellH;positions[id]={x,y};return '<button class="desktop-icon" data-app="'+a[0]+'" data-desktop-shortcut="'+a[0]+'" style="left:'+x+'px;top:'+y+'px" title="'+a[2]+' · Drag to move · Right-click to remove"><span>'+a[1]+'</span><small>'+a[2]+'</small></button>'}).join('');localStorage.setItem('myos-shortcut-positions',JSON.stringify(positions))}
