function showAppFullscreen(id){
 const app=allApps().find(item=>item[0]===id);
 if(!app)return;
 try{
  // Mount with the existing app code, then promote its actual content node to the page.
  openApp(id);
  const w=document.querySelector('#windows .window[data-app="'+CSS.escape(id)+'"]');
  const root=w&&w.querySelector('.window-content');
  if(!w||!root)throw new Error('The app content could not be mounted');
  root.classList.add('myos-standalone-app-root');
  root.remove();
  document.body.insertBefore(root,document.body.firstChild);
  // Remove the OS desktop and the window chrome completely. The app content is now
  // the document's top-level page content, not a window inside the page.
  const desktop=document.getElementById('desktop');
  if(desktop)desktop.remove();
  w.remove();
  const style=document.createElement('style');
  style.id='myos-standalone-app-style';
  style.textContent=`
   html,body{width:100%!important;height:100%!important;min-height:100%!important;margin:0!important;padding:0!important;overflow:hidden!important}
   body{position:relative!important;background:transparent!important}
   .myos-standalone-app-root{display:block!important;position:fixed!important;inset:0!important;width:100vw!important;height:100vh!important;height:100dvh!important;min-width:0!important;min-height:0!important;max-width:none!important;max-height:none!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;transform:none!important;overflow:auto!important;background:transparent!important}
  `;
  document.head.appendChild(style);
  document.title=app[2];
  document.documentElement.dataset.myosStandaloneApp=id;
 }catch(err){console.error('Standalone app launch failed',err)}
}
function openAppInNewTab(id){
 const app=allApps().find(item=>item[0]===id);
 if(!app){toast('This app could not be found');return}
 // Match the OS launcher: open about:blank, fetch the OS HTML, and write it directly.
 const tab=window.open('about:blank','_blank');
 if(!tab){toast('Allow pop-ups to open this app in a new tab');return}
 const base='https://cdn.jsdelivr.net/gh/weirdsimplegames/My-os@main/os/';
 tab.document.open();
 tab.document.write('<!doctype html><html><head><title>Opening '+String(app[2]).replace(/[&<>"]/g,'')+'…</title></head><body style="margin:0;background:#090b12;color:white;font:14px system-ui;padding:24px">Opening app…</body></html>');
 tab.document.close();
 fetch(base+'index.html',{cache:'no-store'}).then(response=>{
  if(!response.ok)throw new Error('Could not load My OS ('+response.status+')');
  return response.text();
 }).then(html=>{
  const baseTag='<base href="'+base+'">';
  if(/<head[^>]*>/i.test(html))html=html.replace(/<head([^>]*)>/i,'<head$1>'+baseTag);
  else html=baseTag+html;
  const launchScript='<script>window.__MYOS_POP_OUT_APP__='+JSON.stringify(id)+';window.addEventListener("load",function(){var appId=window.__MYOS_POP_OUT_APP__;if(appId&&typeof showAppFullscreen==="function")showAppFullscreen(appId);else console.error("App pop-out boot failed: showAppFullscreen is unavailable")});<\/script>';
  html=html.replace(/<\/body>/i,launchScript+'</body>');
  tab.document.open();
  tab.document.write(html);
  tab.document.close();
  tab.document.title=app[2]+' · My OS';
 }).catch(err=>{
  console.error('App pop-out failed:',err);
  try{tab.document.open();tab.document.write('<!doctype html><title>App launch failed</title><body style="font:14px system-ui;padding:24px">Could not load this app. Please refresh My OS and try again.</body>');tab.document.close()}catch{}
 });
}
