const finishShortcutDrag=e=>{if(!shortcutDrag||e.pointerId!==shortcutDrag.pointerId)return;const d=shortcutDrag;shortcutDrag=null;if(shortcutWasDragged){const cellW=88,cellH=100,pad=18,desk=$('#desktop-icons'),cols=Math.max(1,Math.floor(Math.max(0,desk.clientWidth-pad*2)/cellW)),maxRows=Math.max(1,Math.floor(Math.max(0,desk.clientHeight-pad*2)/cellH));let col=Math.max(0,Math.min(cols-1,Math.round(((parseFloat(d.el.style.left)||0)-pad)/cellW))),row=Math.max(0,Math.min(maxRows-1,Math.round(((parseFloat(d.el.style.top)||0)-pad)/cellH))),x=pad+col*cellW,y=pad+row*cellH;d.el.style.left=x+'px';d.el.style.top=y+'px';let positions={};try{positions=JSON.parse(localStorage.getItem('myos-shortcut-positions')||'{}')}catch{}positions[d.id]={x,y};localStorage.setItem('myos-shortcut-positions',JSON.stringify(positions));setTimeout(()=>{shortcutWasDragged=false},0)}};
$('#desktop-icons').addEventListener('pointerup',finishShortcutDrag);$('#desktop-icons').addEventListener('pointercancel',finishShortcutDrag);
document.addEventListener('click',e=>{if(shortcutWasDragged){e.preventDefault();e.stopPropagation();shortcutWasDragged=false;return}let pin=e.target.closest('[data-pin]');if(pin){let id=pin.dataset.pin,p=pinned();p=p.includes(id)?p.filter(x=>x!==id):[...p,id];localStorage.setItem('myos-pinned',JSON.stringify(p));renderApps();return}let shortcut=e.target.closest('[data-shortcut]');if(shortcut){let id=shortcut.dataset.shortcut,s=shortcuts(),removing=s.includes(id);s=removing?s.filter(x=>x!==id):[...s,id];localStorage.setItem('myos-shortcuts',JSON.stringify(s));renderApps();toast(removing?'Desktop shortcut removed':'Desktop shortcut added');return}let a=e.target.closest('button[data-app]');if(a){openApp(a.dataset.app);return}let act=e.target.closest('[data-action]')?.dataset.action;if(act==='launcher')toggle('launcher');if(act==='close-launcher')$('#launcher').classList.add('hidden');if(act==='control')toggle('control-center');if(act==='notifications')toggle('notifications');if(act==='clear-notifications')$('#notification-list').innerHTML='<p class="muted">You’re all caught up.</p>'});
$('#desktop-icons').addEventListener('contextmenu',e=>{const icon=e.target.closest('.desktop-icon[data-app]');if(!icon)return;e.preventDefault();const id=icon.dataset.app,s=shortcuts().filter(x=>x!==id);localStorage.setItem('myos-shortcuts',JSON.stringify(s));renderApps();toast('Desktop shortcut removed')});
$('#app-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();Array.from(document.querySelectorAll('#launcher-apps .launcher-app-wrap')).forEach(b=>{const tile=b.querySelector('.app-tile');b.hidden=!!q&&!(tile?.textContent||'').toLowerCase().includes(q)});};$('#brightness').oninput=e=>$('#desktop').style.filter='brightness('+e.target.value/100+')';$('#volume').oninput=e=>{};
$('#clock').onclick=()=>openApp('calendar');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key===' ')toggle('launcher');if(e.key==='Escape')['launcher','control-center','notifications'].forEach(x=>$('#'+x).classList.add('hidden'))});
renderApps();const fullscreenApp=new URLSearchParams(window.location.search).get('myosApp');if(fullscreenApp)showAppFullscreen(fullscreenApp);apply();loadWallpaper();setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),1000);
